33			// schema-valid deck is served through the stubbed fetch. (This file
34			// typechecks under the DOM tsconfig, so it cannot read the committed
35			// deck off disk; `sequenceClosure.test.ts` proves that one.)
36			stubDeckJson("/thai-script/lessons/lesson-14/deck.json", {
37				lessonId: "lesson-14",
38				title: "The rare tail",
39				slides: [
40					{
41						kind: "retrieval",
42						id: "try",
43						prompt: "Which letter is the rare harbor kh?",
44						revealSlideId: "show",
45					},
46					{
47						kind: "reveal",
48						id: "show",
49						retrievalSlideId: "try",
50						answers: ["ฆ"],
51					},
52				],
53			});
54			const state = app.storage.load();
55			state.completedLessons.push(14);
56			app.storage.save(state);
57			app.value.lesson.reconcileAllContent();
58	
59			renderAt(14, app.value);
60	
61			expect(screen.getByText("New in Lesson 14")).toBeTruthy();
62			// No video slide — the learner already watched it the first time.
63			expect(screen.queryByTitle(/^Lesson 14:/)).toBeNull();
64	
65			// The rare tail is a deck lesson now, so the intro walks the deck
66			// first (its own stepping: Show Answer on retrieval slides, Continue
67			// at the end) and the card slides after. Walk forward until the first
68			// rare vowel (ฤ, named "rue") appears — the rare vowels are exactly
69			// the content this catch-up flow exists for, and reaching one proves
70			// the walk includes them.
71			// The deck arrives through the stubbed fetch, so wait for its first
72			// stepping control before walking.
73			await screen.findByText(/Show Answer|Next|Continue/);
74			let walked = 0;
75			while (screen.queryByText("rue") === null && walked < 60) {
76				const step =
77					screen.queryByText("Show Answer") ??
78					screen.queryByText("Next") ??
79					screen.queryByText("Continue");
80				if (!step) break;
81				fireEvent.click(step);
82				walked += 1;
83			}
84			expect(screen.getByText("rue")).toBeTruthy();
85		});
86	});
