505	/**
506	 * The fewest graduated vocab words that satisfy every prerequisite of
507	 * `entries`: per word class, the largest `minVocabByClass` requirement
508	 * across the entries, taken from the front of `vocabulary.json`'s words of
509	 * that class, plus every `applicationTemplate` function word (which
510	 * `GrammarService.meetsPrerequisites` also requires graduated). Derived
511	 * from the real data rather than hardcoded so a data change moves the
512	 * fixture instead of silently unlocking nothing. `minTotalVocab` is not
513	 * handled — no early entry sets it — and the throw below surfaces the
514	 * moment one does, rather than guessing whether the class minimums happen
515	 * to cover it.
516	 */
517	function vocabSatisfyingPrerequisitesOf(
518		entries: readonly GrammarEntry[],
519	): readonly string[] {
520		const minByClass = new Map<string, number>();
521		for (const entry of entries) {
522			for (const [wordClass, min] of Object.entries(
523				entry.prerequisites.minVocabByClass,
524			)) {
525				minByClass.set(wordClass, Math.max(minByClass.get(wordClass) ?? 0, min));
526			}
527			const required = entry.prerequisites.minTotalVocab ?? 0;
528			if (required > 0) {
529				throw new Error(
530					`grammar entry "${entry.id}" sets minTotalVocab, which this fixture does not derive — extend vocabSatisfyingPrerequisitesOf`,
531				);
532			}
533		}
534	
535		const words: string[] = [];
536		for (const [wordClass, min] of minByClass) {
537			const ofClass = (vocabularyData as VocabEntry[])
538				.filter((word) => word.word_class === wordClass)
539				.slice(0, min);
540			if (ofClass.length < min) {
541				throw new Error(
542					`vocabulary.json has only ${ofClass.length} "${wordClass}" words, ${min} required`,
543				);
544			}
545			words.push(...ofClass.map((word) => word.thai));
546		}
547		for (const entry of entries) {
548			for (const functionWord of entry.applicationTemplate?.functionWords ?? []) {
549				if (!words.includes(functionWord.thai)) {
550					words.push(functionWord.thai);
551				}
552			}
553		}
554		return words;
555	}
556	
557	/**
558	 * Graduating exactly these words (see `makeGraduatedVocabCard` /
559	 * `graduatedVocab`) unlocks the first grammar point — and, with no grammar
560	 * card learned, *only* the first: `getUnlockedGrammarPoints()`'s
561	 * learned-prefix rule keeps every later prerequisite-satisfying point
562	 * locked behind an unlearned earlier one.
563	 */
564	export const UNLOCKS_FIRST_GRAMMAR_POINT: readonly string[] =
565		vocabSatisfyingPrerequisitesOf(GRAMMAR_BY_LESSON.slice(0, 1));
566	
567	/**
568	 * Graduating these words *and* marking the first point learned
569	 * (`learnedGrammar: [FIRST_GRAMMAR_POINT_ID]`) unlocks exactly the first
570	 * two grammar points: the second's prerequisites are met and the only
571	 * earlier point is learned, while everything after stays locked behind the
572	 * unlearned second point.
573	 */
574	export const UNLOCKS_FIRST_TWO_GRAMMAR_POINTS: readonly string[] =
575		vocabSatisfyingPrerequisitesOf(GRAMMAR_BY_LESSON.slice(0, 2));
576	
577	/** A `GameItem` with a pre-assigned direction, for fixed-round tests. */
578	export function makeSymbolItem(
579		symbolCharacter: string,
580		challengeDirection: SymbolChallengeDirection,
581		overrides: Partial<Omit<SymbolItemContent, "kind">> = {},
582	): GameItem {
583		return {
584			kind: "symbol",
585			symbolCharacter,
586			promptText: symbolCharacter,
587			correctAnswer: `${symbolCharacter} name`,
588			audioUrl: `/audio/${symbolCharacter}.mp3`,
589			...overrides,
590			challengeDirection,
591		};
592	}
593	
594	/** A persisted history entry, for seeding history stores. */
595	export function makeHistoryEntry(
596		overrides: Partial<GameHistoryEntry> = {},
597	): GameHistoryEntry {
598		return {
599			kind: "practice",
600			id: "entry-1",
601			playedAt: "2026-09-01T10:00:00.000Z",
602			pools: ["script"],
603			itemCount: 4,
604			summary: {
605				ratingCounts: { 1: 0, 2: 1, 3: 0, 4: 2, 5: 1 },
606				ratedCount: 4,
607				accuracy: 75,
608			},
609			...overrides,
610		};
611	}
612	
613	/** A `JsonStore` whose every load reports corrupt — the unavailable case. */
614	export class CorruptJsonStore<T> implements JsonStore<T> {
615		load(): JsonStoreLoadResult<T> {
616			return { status: "corrupt" };
617		}
618	
619		save(): JsonStoreSaveResult {
620			return { status: "ok" };
621		}
622	}
623	
624	// --- Game use-case factories ---
625	
626	export interface MakeGameOptions {
627		symbols?: readonly string[];
628		historyStore?: JsonStore<GameHistoryEntry[]>;
629	}
630	
631	/** A real `PlayGameUseCase` over in-memory persistence. */
632	export function makeGame(options: MakeGameOptions = {}): PlayGameUseCase {
633		const cardRepo = new StorageCardRepository(new InMemoryStorage());
634		cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
635		return new PlayGameUseCase(
636			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
637			new StorageGameHistoryRepository(
638				options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>(),
639			),
640			// No composition rounds from this factory: it wires one symbol source
641			// and no grammar, so an empty unlocked set is the honest answer.
642			() => [],
643		);
644	}
645	
646	class FixedRoundGame extends PlayGameUseCase {
647		constructor(
648			private readonly fixedItems: readonly GameItem[],
649			selection: GameItemSelectionService,
650			historyRepository: GameHistoryRepository,
651		) {
652			super(selection, historyRepository, () => []);
653		}
654	
655		override startRound(config: GameRoundConfig): GameItem[] {
656			return this.fixedRound(config.itemCount);
657		}
658	
659		/**
660		 * Composition rounds are fixed the same way practice rounds are, so a
661		 * page test can drive either mode from one list of pre-built items.
662		 */
663		override startCompositionRound(count: number): GameItem[] {
664			return this.fixedRound(count);
665		}
666	
667		private fixedRound(count: number): GameItem[] {
668			return this.fixedItems.slice(
669				0,
670				normalizeRequestedCount(count, this.fixedItems.length),
671			);
672		}
673	}
674	
675	/**
676	 * A `PlayGameUseCase` whose rounds are exactly `items`, in order, with the
677	 * directions the test pre-assigned — everything else (rating, finishing,
678	 * history) stays real.
679	 */
680	export function makeFixedRoundGame(
681		items: readonly GameItem[],
682		options: Pick<MakeGameOptions, "historyStore"> = {},
683	): { game: PlayGameUseCase; historyStore: JsonStore<GameHistoryEntry[]> } {
684		const historyStore =
685			options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>();
686		const cardRepo = new StorageCardRepository(new InMemoryStorage());
687		const game = new FixedRoundGame(
688			items,
689			new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
690			new StorageGameHistoryRepository(historyStore),
691		);
692		return { game, historyStore };
693	}
694	
695	// --- Conversation practice port stub ---
696	
697	/**
698	 * A `ConversationPracticePort` that answers with whatever the test sets and
699	 * records what it was asked. Defaults to `"unavailable"` on every call — the
700	 * honest default for a harness with no backend behind it.
701	 *
702	 * `next` and `judgement` are queues, not single values: a multi-turn test
703	 * (task 3.3) drives several turns in one render, and each one needs its own
704	 * answer — `nextResults`/`judgements` are shifted one at a time, falling
705	 * back to the last-set single value once exhausted so a single-turn test
706	 * can keep just setting `.judgement`/`.session` without touching the queues.
707	 */
708	export class StubConversationPracticePort implements ConversationPracticePort {
709		session: ConversationSessionStartResult = { status: "unavailable" };
710		judgement: ConversationJudgeResult = { status: "unavailable" };
711		nextResult: ConversationNextResult = { status: "exhausted" };
712		readonly nextResults: ConversationNextResult[] = [];
713		readonly judgements: ConversationJudgeResult[] = [];
714		readonly startSessionCalls: string[][] = [];
715		readonly nextCalls: string[] = [];
716		readonly judgeCalls: {
717			sessionId: string;
718			questionText: string;
719			replyAudio: Blob;
720		}[] = [];
721	
722		async startSession(
723			knownWords: string[],
724		): Promise<ConversationSessionStartResult> {
725			this.startSessionCalls.push(knownWords);
726			return this.session;
727		}
728	
729		async next(sessionId: string): Promise<ConversationNextResult> {
730			this.nextCalls.push(sessionId);
731			return this.nextResults.length > 0
732				? (this.nextResults.shift() as ConversationNextResult)
733				: this.nextResult;
734		}
735	
736		async judgeReply(
737			sessionId: string,
738			questionText: string,
739			replyAudio: Blob,
740		): Promise<ConversationJudgeResult> {
741			this.judgeCalls.push({ sessionId, questionText, replyAudio });
742			return this.judgements.length > 0
743				? (this.judgements.shift() as ConversationJudgeResult)
744				: this.judgement;
745		}
746	}
747	
748	// --- The harness itself ---
749	
750	export interface AppHarness {
751		value: AppContextValue;
752		storage: InMemoryStorage;
753		cardRepo: StorageCardRepository;
754		historyStore: InMemoryJsonStore<GameHistoryEntry[]>;
755		game: PlayGameUseCase;
756	}
757	
758	export interface MakeAppValueOptions {
759		/** Characters (existing in `symbols.ts`) to seed one script card each for. */
760		symbols?: readonly string[];
761		/** Sentence ids (existing in `sentences.json`) to seed one card each for. */
762		sentences?: readonly string[];
763		/**
764		 * Thai words (existing in `vocabulary.json`) to seed one
765		 * `toneIdentification` card each for — what makes a word eligible for
766		 * tone practice.
767		 */
768		toneWords?: readonly string[];
769		/**
770		 * Thai words (existing in `vocabulary.json`) to seed one *graduated*
771		 * vocab card each for — what counts toward grammar prerequisites and so
772		 * toward composition mode's unlocked set. `UNLOCKS_FIRST_GRAMMAR_POINT`
773		 * is the derived set that unlocks exactly the first grammar point.
774		 */
775		graduatedVocab?: readonly string[];
776		/**
777		 * Grammar ids (existing in `grammar.json`) to seed one grammar card
778		 * each for — what marks those points *learned*, letting later points
779		 * unlock once their own prerequisites are met.
780		 */
781		learnedGrammar?: readonly string[];
782		/**
783		 * Pre-built cards to seed as-is, for shapes the named options above don't
784		 * cover (e.g. a `selfValidation` sentence card, built with
785		 * `makeSelfValidationSentenceCard`).
786		 */
787		extraCards?: readonly ReviewableCard[];
788	}
789	
790	/**
791	 * A complete in-memory `AppContextValue`: every use case and service the
792	 * real `AppContext.tsx` wires, built over `InMemoryStorage` instead of
793	 * `localStorage`, plus a real `PlayGameUseCase` over an in-memory history
794	 * store. `refresh` and `checkAchievements` are inert stubs — pass overrides
795	 * if a test needs either to be observable.
796	 */
797	export function makeAppValue(options: MakeAppValueOptions = {}): AppHarness {
798		const storage = new InMemoryStorage();
799		const cardRepo = new StorageCardRepository(storage);
800		const stateRepo = new StorageLearnerStateRepository(storage);
801		const apprenticeService = new ApprenticeService(
802			cardRepo,
803			MAX_APPRENTICE_ITEMS,
804			stateRepo,
805		);
806		const leechService = new LeechService(cardRepo);
807		const learningService = new LearningService(
808			cardRepo,
809			stateRepo,
810			apprenticeService,
811		);
812		const reviewService = new ReviewService(cardRepo, stateRepo, {
813			// Sentence sessions are chosen by coverage of the material rather than
814			// by per-card overdueness — see `SentenceCoverageSelector`.
815			sentence: new SentenceCoverageSelector(
816				sentenceData as unknown as SentenceEntry[],
817			),
818		});
819		const vocabularyService = new VocabularyService(
820			cardRepo,
821			stateRepo,
822			vocabularyData as VocabEntry[],
823			apprenticeService,
824		);
825		const grammarService = new GrammarService(
826			cardRepo,
827			grammarData as unknown as GrammarEntry[],
828			apprenticeService,
829			vocabularyData as VocabEntry[],
830		);
831		const sentenceService = new SentenceService(
832			cardRepo,
833			sentenceData as unknown as SentenceEntry[],
834			vocabularyService,
835			apprenticeService,
836		);
837	
838		cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
839		cardRepo.saveAll((options.sentences ?? []).map(makeSentenceCard));
840		cardRepo.saveAll((options.toneWords ?? []).map(makeToneVocabCard));
841		cardRepo.saveAll((options.graduatedVocab ?? []).map(makeGraduatedVocabCard));
842		cardRepo.saveAll((options.learnedGrammar ?? []).map(makeGrammarCard));
843		cardRepo.saveAll([...(options.extraCards ?? [])]);
844	
845		const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
846		// Register every source the real `AppContext.tsx` registers — a harness
847		// that registers a subset silently diverges from production per pool
848		// (see task 1.3), which is how "works in the harness, empty in the app"
849		// bugs are born.
850		const game = new PlayGameUseCase(
851			new GameItemSelectionService(
852				[
853					new SymbolGameItemSource(cardRepo),
854					new WordGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
855					new SentenceGameItemSource(
856						cardRepo,
857						sentenceData as unknown as SentenceEntry[],
858					),
859				],
860				cardRepo,
861				new ToneGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
862			),
863			new StorageGameHistoryRepository(historyStore),
864			// The real `GrammarService`, exactly as `AppContext.tsx` wires it — a
865			// harness that stubs this diverges from production on the one
866			// question composition mode asks (see task 1.3's own note above).
867			() => grammarService.getUnlockedGrammarPoints(),
868		);
869	
870		const value: AppContextValue = {
871			state: storage.load(),
872			refresh: () => {},
873			lesson: new StartLessonUseCase(
874				learningService,
875				vocabularyService,
876				grammarService,
877				sentenceService,
878			),
879			review: new ConductReviewUseCase(
880				reviewService,
881				new NotificationScheduler(),
882			),
883			dashboard: new QueryDashboardUseCase(
884				cardRepo,
885				apprenticeService,
886				leechService,
887			),
888			data: new ManageDataUseCase(stateRepo),
889			items: new ManageItemsUseCase(cardRepo),
890			vocab: vocabularyService,
891			conversationPractice: new StubConversationPracticePort(),
892			sentence: sentenceService,
893			checkAchievements: () => [],
894			game,
895		};
896	
897		return { value, storage, cardRepo, historyStore, game };
898	}
899	
900	export interface RenderWithAppOptions extends MakeAppValueOptions {
901		/** Initial router entry, default `/`. */
902		route?: string;
903	}
904	
905	/**
906	 * Renders `ui` inside `<AppContext.Provider>` (a fresh in-memory
907	 * `AppContextValue`, with `overrides` merged in) and a `MemoryRouter`.
908	 * Returns Testing-Library's render result plus the harness internals.
909	 */
910	export function renderWithApp(
911		ui: ReactElement,
912		overrides: Partial<AppContextValue> = {},
913		options: RenderWithAppOptions = {},
914	): RenderResult & { app: AppHarness } {
915		const app = makeAppValue({
916			symbols: options.symbols,
917			sentences: options.sentences,
918			toneWords: options.toneWords,
919			graduatedVocab: options.graduatedVocab,
920			learnedGrammar: options.learnedGrammar,
921			extraCards: options.extraCards,
922		});
923		const value: AppContextValue = { ...app.value, ...overrides };
924		const result = render(
925			<AppContext.Provider value={value}>
926				<MemoryRouter initialEntries={[options.route ?? "/"]}>{ui}</MemoryRouter>
927			</AppContext.Provider>,
928		);
929		return Object.assign(result, { app: { ...app, value, game: value.game } });
930	}
