/**
 * Page-level render-test harness — the first in this repository.
 *
 * Importing this module registers the environment repairs every page-level
 * render test needs and that no global vitest config provides (see
 * CONTEXT.md):
 *
 * - an explicit `afterEach(cleanup)` — there is no `globals: true` /
 *   `setupFiles`, so Testing-Library's auto-cleanup never registers;
 * - a hand-built `localStorage` on `globalThis` — jsdom under vitest 4 in
 *   this repo leaves it undefined (Node's own experimental global
 *   conflicts), so tests stub a Storage-shaped fake instead;
 * - a stubbed `Audio` constructor that records constructed URLs (jsdom's
 *   `HTMLMediaElement.play` throws synchronously) plus prototype stubs for
 *   `play`/`pause` for any real media element;
 * - a stubbed `HTMLCanvasElement.getContext` returning a shared recording
 *   2D context (jsdom has none without the `canvas` package), which also
 *   lets tests observe `clearRect` calls;
 * - `URL.createObjectURL`/`revokeObjectURL` (jsdom implements neither), so
 *   any code that turns a `Blob` into a playable URL runs instead of
 *   throwing;
 * - a `MediaRecorder` recording one fixed `Blob` and a
 *   `navigator.mediaDevices.getUserMedia` whose outcome `setMicPermission`
 *   chooses (jsdom has neither) — between them enough for a test to drive
 *   `useMicRecorder`'s real state machine, refusal included.
 * - a stubbed `fetch` (jsdom has none), returning JSON bodies registered
 *   with `stubDeckJson`/`stubDeckFetchError` and 404-ing anything else, for
 *   `DeckSlide`'s deck-JSON load.
 *
 * Test files still need their own `// @vitest-environment jsdom` docblock —
 * the pragma only works in the test file itself.
 */
import { cleanup, type RenderResult, render } from "@testing-library/react";
import type { ReactElement } from "react";
import { MemoryRouter } from "react-router";
import { afterEach, beforeEach, vi } from "vitest";
import { ConductReviewUseCase } from "../../application/use-cases/ConductReviewUseCase";
import { ManageDataUseCase } from "../../application/use-cases/ManageDataUseCase";
import { ManageItemsUseCase } from "../../application/use-cases/ManageItemsUseCase";
import { PlayGameUseCase } from "../../application/use-cases/PlayGameUseCase";
import { QueryDashboardUseCase } from "../../application/use-cases/QueryDashboardUseCase";
import { StartLessonUseCase } from "../../application/use-cases/StartLessonUseCase";
import type {
	ConversationJudgeResult,
	ConversationNextResult,
	ConversationSessionStartResult,
} from "../../domain/conversation/types";
import type { GameHistoryRepository } from "../../domain/game/ports/GameHistoryRepository";
import { GameItemSelectionService } from "../../domain/game/services/GameItemSelectionService";
import { SentenceGameItemSource } from "../../domain/game/services/SentenceGameItemSource";
import { SymbolGameItemSource } from "../../domain/game/services/SymbolGameItemSource";
import { normalizeRequestedCount } from "../../domain/game/services/sampling";
import { ToneGameItemSource } from "../../domain/game/services/ToneGameItemSource";
import { WordGameItemSource } from "../../domain/game/services/WordGameItemSource";
import type {
	GameHistoryEntry,
	GameItem,
	GameRoundConfig,
	SymbolChallengeDirection,
	SymbolItemContent,
} from "../../domain/game/types";
import grammarData from "../../domain/grammar/data/grammar.json";
import { GrammarReviewCard } from "../../domain/grammar/entities/GrammarReviewCard";
import { GrammarService } from "../../domain/grammar/services/GrammarLessonService";
import type { GrammarEntry } from "../../domain/grammar/types";
import type { ConversationPracticePort } from "../../domain/ports/ConversationPracticePort";
import { ScriptPropertyCard } from "../../domain/script/entities/ScriptPropertyCard";
import { LearningService } from "../../domain/script/services/ScriptLessonService";
import sentenceData from "../../domain/sentence/data/sentences.json";
import { SentenceReviewCard } from "../../domain/sentence/entities/SentenceReviewCard";
import { SentenceCoverageSelector } from "../../domain/sentence/services/SentenceCoverageSelector";
import { SentenceService } from "../../domain/sentence/services/SentenceLessonService";
import type { SentenceEntry } from "../../domain/sentence/types";
import { ReviewService } from "../../domain/session/services/ReviewService";
import {
	ApprenticeService,
	MAX_APPRENTICE_ITEMS,
} from "../../domain/shared/services/ApprenticeService";
import { LeechService } from "../../domain/shared/services/LeechService";
import type { ReviewableCard } from "../../domain/srs/entities/ReviewableCard";
import vocabularyData from "../../domain/vocabulary/data/vocabulary.json";
import { VocabCard } from "../../domain/vocabulary/entities/VocabCard";
import { toneSyllablesOf } from "../../domain/vocabulary/services/toneSyllables";
import { VocabularyService } from "../../domain/vocabulary/services/VocabularyLessonService";
import type { VocabEntry } from "../../domain/vocabulary/types";
import { NotificationScheduler } from "../../infrastructure/notifications/NotificationScheduler";
import {
	InMemoryJsonStore,
	type JsonStore,
	type JsonStoreLoadResult,
	type JsonStoreSaveResult,
} from "../../infrastructure/persistence/JsonStore";
import { InMemoryStorage } from "../../infrastructure/persistence/Storage";
import { StorageCardRepository } from "../../infrastructure/persistence/StorageCardRepository";
import { StorageGameHistoryRepository } from "../../infrastructure/persistence/StorageGameHistoryRepository";
import { StorageLearnerStateRepository } from "../../infrastructure/persistence/StorageLearnerStateRepository";
import { AppContext, type AppContextValue } from "../context/AppContext";

// --- localStorage fake (jsdom's own is unreliable here, see module docs) ---

export class FakeLocalStorage implements Storage {
	private store = new Map<string, string>();

	get length(): number {
		return this.store.size;
	}

	clear(): void {
		this.store.clear();
	}

	getItem(key: string): string | null {
		return this.store.has(key) ? (this.store.get(key) as string) : null;
	}

	key(index: number): string | null {
		return Array.from(this.store.keys())[index] ?? null;
	}

	removeItem(key: string): void {
		this.store.delete(key);
	}

	setItem(key: string, value: string): void {
		this.store.set(key, value);
	}
}

let fakeLocalStorage = new FakeLocalStorage();

/** The per-test `localStorage` stand-in installed on `globalThis`. */
export function getFakeLocalStorage(): FakeLocalStorage {
	return fakeLocalStorage;
}

// --- Audio stub (jsdom throws synchronously from `play()`) ---

export class StubAudio {
	static createdUrls: string[] = [];
	currentTime = 0;

	constructor(readonly src?: string) {
		StubAudio.createdUrls.push(src ?? "");
	}

	play(): Promise<void> {
		return Promise.resolve();
	}

	pause(): void {}
}

/** URLs passed to `new Audio(url)` since the current test began. */
export function createdAudioUrls(): readonly string[] {
	return StubAudio.createdUrls;
}

// --- Object-URL stub (jsdom implements neither create nor revoke) ---

let objectUrlCount = 0;
let revokedUrls: string[] = [];

/** URLs passed to `URL.revokeObjectURL` since the current test began. */
export function revokedObjectUrls(): readonly string[] {
	return revokedUrls;
}

// --- Microphone stubs (jsdom has neither `MediaRecorder` nor `mediaDevices`) ---

/** The MIME type and bytes every stubbed recording produces. */
export const MIC_FIXTURE_MIME_TYPE = "audio/webm;codecs=opus";
const MIC_FIXTURE_BYTES = Uint8Array.from([0x1a, 0x45, 0xdf, 0xa3]);

export type MicPermission = "granted" | "denied" | "error";

let micPermission: MicPermission = "granted";

/**
 * What the next `getUserMedia` call does: hand back a stream, refuse with a
 * `NotAllowedError` (the permission prompt declined), or fail some other way
 * — the three outcomes `useMicRecorder` maps to `recording`/`denied`/`error`.
 * Resets to `"granted"` before each test.
 */
export function setMicPermission(permission: MicPermission): void {
	micPermission = permission;
}

/**
 * A `MediaRecorder` that records one fixed `Blob`. `stop()` synchronously
 * emits the fixture and fires `onstop`, so a test drives the real
 * `useMicRecorder` state machine without any timing games.
 */
export class StubMediaRecorder {
	state: "inactive" | "recording" = "inactive";
	ondataavailable: ((event: { data: Blob }) => void) | null = null;
	onstop: (() => void) | null = null;

	readonly mimeType = MIC_FIXTURE_MIME_TYPE;

	start(): void {
		this.state = "recording";
	}

	stop(): void {
		this.state = "inactive";
		this.ondataavailable?.({
			data: new Blob([MIC_FIXTURE_BYTES], { type: MIC_FIXTURE_MIME_TYPE }),
		});
		this.onstop?.();
	}
}

// --- fetch stub (jsdom has none; `DeckSlide` loads deck JSON with it) ---

type FetchOutcome =
	| { readonly kind: "json"; readonly body: unknown; readonly status: number }
	| { readonly kind: "error" };

let fetchOutcomes = new Map<string, FetchOutcome>();

/** The next `fetch(url)` in this test resolves with `body` as JSON. */
export function stubDeckJson(url: string, body: unknown, status = 200): void {
	fetchOutcomes.set(url, { kind: "json", body, status });
}

/** The next `fetch(url)` in this test rejects, as a network failure would. */
export function stubDeckFetchError(url: string): void {
	fetchOutcomes.set(url, { kind: "error" });
}

// --- Canvas 2D stub (jsdom has no 2D context without the canvas package) ---

export const canvas2d = {
	clearRect: vi.fn(),
	beginPath: vi.fn(),
	moveTo: vi.fn(),
	lineTo: vi.fn(),
	stroke: vi.fn(),
	lineCap: "round",
	lineJoin: "round",
	lineWidth: 4,
	strokeStyle: "",
};

beforeEach(() => {
	fakeLocalStorage = new FakeLocalStorage();
	globalThis.localStorage = fakeLocalStorage;
	globalThis.Audio = StubAudio as unknown as typeof Audio;
	StubAudio.createdUrls = [];
	fetchOutcomes = new Map();
	globalThis.fetch = (async (input: RequestInfo | URL) => {
		const url = typeof input === "string" ? input : input.toString();
		const outcome = fetchOutcomes.get(url);
		if (!outcome || outcome.kind === "error") {
			return {
				ok: false,
				status: 404,
				json: async () => {
					throw new Error(`no fetch stub registered for ${url}`);
				},
			} as unknown as Response;
		}
		return {
			ok: outcome.status >= 200 && outcome.status < 300,
			status: outcome.status,
			json: async () => outcome.body,
		} as unknown as Response;
	}) as typeof fetch;
	objectUrlCount = 0;
	revokedUrls = [];
	URL.createObjectURL = () => {
		objectUrlCount += 1;
		return `blob:test/${objectUrlCount}`;
	};
	URL.revokeObjectURL = (url: string) => {
		revokedUrls.push(url);
	};
	micPermission = "granted";
	globalThis.MediaRecorder =
		StubMediaRecorder as unknown as typeof MediaRecorder;
	Object.defineProperty(globalThis.navigator, "mediaDevices", {
		configurable: true,
		value: {
			getUserMedia: async () => {
				if (micPermission === "denied") {
					throw new DOMException("Permission denied", "NotAllowedError");
				}
				if (micPermission === "error") {
					throw new Error("No recording device");
				}
				return {
					getTracks: () => [{ stop: () => {} }],
				} as unknown as MediaStream;
			},
		},
	});
	canvas2d.clearRect.mockClear();
	canvas2d.beginPath.mockClear();
	canvas2d.moveTo.mockClear();
	canvas2d.lineTo.mockClear();
	canvas2d.stroke.mockClear();
	if (typeof HTMLMediaElement !== "undefined") {
		HTMLMediaElement.prototype.play = () => Promise.resolve();
		HTMLMediaElement.prototype.pause = () => {};
	}
	if (typeof HTMLCanvasElement !== "undefined") {
		HTMLCanvasElement.prototype.getContext = (() =>
			canvas2d) as unknown as HTMLCanvasElement["getContext"];
	}
});

afterEach(() => {
	cleanup();
	Reflect.deleteProperty(globalThis, "localStorage");
});

// --- Fixtures ---

const DEFAULT_SRS = {
	easeFactor: 2.0,
	interval: 10,
	repetitions: 0,
	learningStep: 1,
	nextReviewDate: "2026-01-01T00:00:00.000Z",
	lastReviewDate: null,
	lapseCount: 0,
};

/**
 * One script card for `symbolCharacter` — enough to make that symbol
 * eligible (eligibility is card-driven; content still comes from
 * `symbols.ts`, so pass characters that exist there, e.g. "ม", "น", "ง").
 */
export function makeScriptCard(symbolCharacter: string): ScriptPropertyCard {
	return ScriptPropertyCard.fromDTO({
		id: `${symbolCharacter}-recognition`,
		question: `What sound does ${symbolCharacter} make?`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: { ...DEFAULT_SRS },
		symbolCharacter,
		property: "recognition",
		lessonNumber: 1,
	});
}

/**
 * A script card with an explicit SRS history — for weighting/weak-item tests.
 */
export function scriptCardWith(
	symbolCharacter: string,
	easeFactor: number,
	lapseCount: number,
	repetitions: number,
): ScriptPropertyCard {
	return ScriptPropertyCard.fromDTO({
		id: `${symbolCharacter}-recognition`,
		question: "question",
		correctAnswer: "answer",
		choices: ["answer"],
		srs: {
			easeFactor,
			interval: 10,
			repetitions,
			learningStep: null,
			nextReviewDate: "2026-01-01T00:00:00.000Z",
			lastReviewDate: "2026-01-01T00:00:00.000Z",
			lapseCount,
		},
		symbolCharacter,
		property: "recognition",
		lessonNumber: 1,
	});
}

/**
 * One sentence review card for `sentenceId` — enough to make that sentence
 * eligible (eligibility is card-driven; content still comes from
 * `sentences.json`, so pass ids that exist there, e.g. "basic-001").
 */
export function makeSentenceCard(sentenceId: string): SentenceReviewCard {
	return SentenceReviewCard.fromDTO({
		id: `sentence:${sentenceId}:readingComprehension`,
		question: `question for ${sentenceId}`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: { ...DEFAULT_SRS },
		sentenceId,
		property: "readingComprehension",
	});
}

/**
 * One `selfValidation` sentence review card for `sentenceId`, matching what
 * `SentenceCardGenerator` actually produces for that property: an empty
 * `choices` array (it's a produce-then-self-rate card, never a
 * multiple-choice one) at the same non-null `learningStep` every freshly
 * learned card starts at.
 */
export function makeSelfValidationSentenceCard(
	sentenceId: string,
): SentenceReviewCard {
	return SentenceReviewCard.fromDTO({
		id: `sentence:${sentenceId}:selfValidation`,
		question: `question for ${sentenceId}`,
		correctAnswer: "answer",
		choices: [],
		srs: { ...DEFAULT_SRS },
		sentenceId,
		property: "selfValidation",
	});
}

/**
 * One `toneIdentification` vocab card for `thai` — enough to make that word
 * eligible for tone practice (eligibility is card-driven; the item's
 * content still comes from the matching `VocabEntry`, so pass Thai words
 * that exist in `vocabulary.json`, e.g. "ที่", "ได้", "จะ", "นี้").
 *
 * The card carries the word's real syllables, exactly as
 * `VocabCardGenerator` writes them, so a fixture can never accidentally
 * prove more than production does — but nothing reads them: a card
 * persisted before that field existed has `syllables === undefined`, which
 * is why `ToneGameItemSource` sources its content from the entry instead
 * (see CONTEXT.md).
 */
export function makeToneVocabCard(thai: string): VocabCard {
	const entry = (vocabularyData as VocabEntry[]).find(
		(word) => word.thai === thai,
	);
	if (!entry) {
		throw new Error(`no vocabulary entry for "${thai}"`);
	}
	return VocabCard.fromDTO({
		id: `vocab:${thai}:toneIdentification`,
		question: `What is the tone pattern of ${thai}?`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: { ...DEFAULT_SRS },
		promptWord: thai,
		property: "toneIdentification",
		syllables: toneSyllablesOf(entry),
	});
}

/**
 * One *graduated* vocab card for `thai` — `srs.learningStep: null`, which
 * is what `GrammarService.getMasteredVocabCounts()` counts toward grammar
 * prerequisites (`DEFAULT_SRS` above graduates nothing). The word must
 * exist in `vocabulary.json`: a graduated card for a word the data doesn't
 * carry counts toward no `word_class` at all, which is exactly the silent
 * fixture typo this check exists to catch.
 */
export function makeGraduatedVocabCard(thai: string): VocabCard {
	const entry = (vocabularyData as VocabEntry[]).find(
		(word) => word.thai === thai,
	);
	if (!entry) {
		throw new Error(`no vocabulary entry for "${thai}"`);
	}
	return VocabCard.fromDTO({
		id: `vocab:${thai}:thaiToEnglish`,
		question: `What does ${thai} mean?`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: { ...DEFAULT_SRS, learningStep: null },
		promptWord: thai,
		property: "thaiToEnglish",
	});
}

/**
 * One grammar card for `grammarId` — what marks that grammar point
 * *learned* for `GrammarService.getUnlockedGrammarPoints()`'s
 * learned-prefix rule, letting the next point unlock once its own
 * prerequisites are met. The content fields are inert: nothing in the game
 * feature reads a grammar card beyond its `grammarId`'s existence.
 */
export function makeGrammarCard(grammarId: string): GrammarReviewCard {
	return GrammarReviewCard.fromDTO({
		id: `grammar:${grammarId}:recognition`,
		question: `question for ${grammarId}`,
		correctAnswer: "answer",
		choices: ["answer", "other"],
		srs: { ...DEFAULT_SRS },
		grammarId,
		property: "recognition",
	});
}

// --- Grammar-unlock fixtures, derived from the real data ---

const GRAMMAR_BY_LESSON: readonly GrammarEntry[] = [
	...(grammarData as unknown as GrammarEntry[]),
].sort((a, b) => a.lessonNumber - b.lessonNumber);

const firstGrammarEntry = GRAMMAR_BY_LESSON[0];
if (!firstGrammarEntry) {
	throw new Error("grammar.json is empty — the unlock fixtures need data");
}

/** The id `makeGrammarCard` needs to mark the first grammar point learned. */
export const FIRST_GRAMMAR_POINT_ID: string = firstGrammarEntry.id;

/**
 * The fewest graduated vocab words that satisfy every prerequisite of
 * `entries`: per word class, the largest `minVocabByClass` requirement
 * across the entries, taken from the front of `vocabulary.json`'s words of
 * that class, plus every `applicationTemplate` function word (which
 * `GrammarService.meetsPrerequisites` also requires graduated). Derived
 * from the real data rather than hardcoded so a data change moves the
 * fixture instead of silently unlocking nothing. `minTotalVocab` is not
 * handled — no early entry sets it — and the throw below surfaces the
 * moment one does, rather than guessing whether the class minimums happen
 * to cover it.
 */
function vocabSatisfyingPrerequisitesOf(
	entries: readonly GrammarEntry[],
): readonly string[] {
	const minByClass = new Map<string, number>();
	for (const entry of entries) {
		for (const [wordClass, min] of Object.entries(
			entry.prerequisites.minVocabByClass,
		)) {
			minByClass.set(wordClass, Math.max(minByClass.get(wordClass) ?? 0, min));
		}
		const required = entry.prerequisites.minTotalVocab ?? 0;
		if (required > 0) {
			throw new Error(
				`grammar entry "${entry.id}" sets minTotalVocab, which this fixture does not derive — extend vocabSatisfyingPrerequisitesOf`,
			);
		}
	}

	const words: string[] = [];
	for (const [wordClass, min] of minByClass) {
		const ofClass = (vocabularyData as VocabEntry[])
			.filter((word) => word.word_class === wordClass)
			.slice(0, min);
		if (ofClass.length < min) {
			throw new Error(
				`vocabulary.json has only ${ofClass.length} "${wordClass}" words, ${min} required`,
			);
		}
		words.push(...ofClass.map((word) => word.thai));
	}
	for (const entry of entries) {
		for (const functionWord of entry.applicationTemplate?.functionWords ?? []) {
			if (!words.includes(functionWord.thai)) {
				words.push(functionWord.thai);
			}
		}
	}
	return words;
}

/**
 * Graduating exactly these words (see `makeGraduatedVocabCard` /
 * `graduatedVocab`) unlocks the first grammar point — and, with no grammar
 * card learned, *only* the first: `getUnlockedGrammarPoints()`'s
 * learned-prefix rule keeps every later prerequisite-satisfying point
 * locked behind an unlearned earlier one.
 */
export const UNLOCKS_FIRST_GRAMMAR_POINT: readonly string[] =
	vocabSatisfyingPrerequisitesOf(GRAMMAR_BY_LESSON.slice(0, 1));

/**
 * Graduating these words *and* marking the first point learned
 * (`learnedGrammar: [FIRST_GRAMMAR_POINT_ID]`) unlocks exactly the first
 * two grammar points: the second's prerequisites are met and the only
 * earlier point is learned, while everything after stays locked behind the
 * unlearned second point.
 */
export const UNLOCKS_FIRST_TWO_GRAMMAR_POINTS: readonly string[] =
	vocabSatisfyingPrerequisitesOf(GRAMMAR_BY_LESSON.slice(0, 2));

/** A `GameItem` with a pre-assigned direction, for fixed-round tests. */
export function makeSymbolItem(
	symbolCharacter: string,
	challengeDirection: SymbolChallengeDirection,
	overrides: Partial<Omit<SymbolItemContent, "kind">> = {},
): GameItem {
	return {
		kind: "symbol",
		symbolCharacter,
		promptText: symbolCharacter,
		correctAnswer: `${symbolCharacter} name`,
		audioUrl: `/audio/${symbolCharacter}.mp3`,
		...overrides,
		challengeDirection,
	};
}

/** A persisted history entry, for seeding history stores. */
export function makeHistoryEntry(
	overrides: Partial<GameHistoryEntry> = {},
): GameHistoryEntry {
	return {
		kind: "practice",
		id: "entry-1",
		playedAt: "2026-09-01T10:00:00.000Z",
		pools: ["script"],
		itemCount: 4,
		summary: {
			ratingCounts: { 1: 0, 2: 1, 3: 0, 4: 2, 5: 1 },
			ratedCount: 4,
			accuracy: 75,
		},
		...overrides,
	};
}

/** A `JsonStore` whose every load reports corrupt — the unavailable case. */
export class CorruptJsonStore<T> implements JsonStore<T> {
	load(): JsonStoreLoadResult<T> {
		return { status: "corrupt" };
	}

	save(): JsonStoreSaveResult {
		return { status: "ok" };
	}
}

// --- Game use-case factories ---

export interface MakeGameOptions {
	symbols?: readonly string[];
	historyStore?: JsonStore<GameHistoryEntry[]>;
}

/** A real `PlayGameUseCase` over in-memory persistence. */
export function makeGame(options: MakeGameOptions = {}): PlayGameUseCase {
	const cardRepo = new StorageCardRepository(new InMemoryStorage());
	cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
	return new PlayGameUseCase(
		new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
		new StorageGameHistoryRepository(
			options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>(),
		),
		// No composition rounds from this factory: it wires one symbol source
		// and no grammar, so an empty unlocked set is the honest answer.
		() => [],
	);
}

class FixedRoundGame extends PlayGameUseCase {
	constructor(
		private readonly fixedItems: readonly GameItem[],
		selection: GameItemSelectionService,
		historyRepository: GameHistoryRepository,
	) {
		super(selection, historyRepository, () => []);
	}

	override startRound(config: GameRoundConfig): GameItem[] {
		return this.fixedRound(config.itemCount);
	}

	/**
	 * Composition rounds are fixed the same way practice rounds are, so a
	 * page test can drive either mode from one list of pre-built items.
	 */
	override startCompositionRound(count: number): GameItem[] {
		return this.fixedRound(count);
	}

	private fixedRound(count: number): GameItem[] {
		return this.fixedItems.slice(
			0,
			normalizeRequestedCount(count, this.fixedItems.length),
		);
	}
}

/**
 * A `PlayGameUseCase` whose rounds are exactly `items`, in order, with the
 * directions the test pre-assigned — everything else (rating, finishing,
 * history) stays real.
 */
export function makeFixedRoundGame(
	items: readonly GameItem[],
	options: Pick<MakeGameOptions, "historyStore"> = {},
): { game: PlayGameUseCase; historyStore: JsonStore<GameHistoryEntry[]> } {
	const historyStore =
		options.historyStore ?? new InMemoryJsonStore<GameHistoryEntry[]>();
	const cardRepo = new StorageCardRepository(new InMemoryStorage());
	const game = new FixedRoundGame(
		items,
		new GameItemSelectionService([new SymbolGameItemSource(cardRepo)]),
		new StorageGameHistoryRepository(historyStore),
	);
	return { game, historyStore };
}

// --- Conversation practice port stub ---

/**
 * A `ConversationPracticePort` that answers with whatever the test sets and
 * records what it was asked. Defaults to `"unavailable"` on every call — the
 * honest default for a harness with no backend behind it.
 *
 * `next` and `judgement` are queues, not single values: a multi-turn test
 * (task 3.3) drives several turns in one render, and each one needs its own
 * answer — `nextResults`/`judgements` are shifted one at a time, falling
 * back to the last-set single value once exhausted so a single-turn test
 * can keep just setting `.judgement`/`.session` without touching the queues.
 */
export class StubConversationPracticePort implements ConversationPracticePort {
	session: ConversationSessionStartResult = { status: "unavailable" };
	judgement: ConversationJudgeResult = { status: "unavailable" };
	nextResult: ConversationNextResult = { status: "exhausted" };
	readonly nextResults: ConversationNextResult[] = [];
	readonly judgements: ConversationJudgeResult[] = [];
	readonly startSessionCalls: string[][] = [];
	readonly nextCalls: string[] = [];
	readonly judgeCalls: {
		sessionId: string;
		questionText: string;
		replyAudio: Blob;
	}[] = [];

	async startSession(
		knownWords: string[],
	): Promise<ConversationSessionStartResult> {
		this.startSessionCalls.push(knownWords);
		return this.session;
	}

	async next(sessionId: string): Promise<ConversationNextResult> {
		this.nextCalls.push(sessionId);
		return this.nextResults.length > 0
			? (this.nextResults.shift() as ConversationNextResult)
			: this.nextResult;
	}

	async judgeReply(
		sessionId: string,
		questionText: string,
		replyAudio: Blob,
	): Promise<ConversationJudgeResult> {
		this.judgeCalls.push({ sessionId, questionText, replyAudio });
		return this.judgements.length > 0
			? (this.judgements.shift() as ConversationJudgeResult)
			: this.judgement;
	}
}

// --- The harness itself ---

export interface AppHarness {
	value: AppContextValue;
	storage: InMemoryStorage;
	cardRepo: StorageCardRepository;
	historyStore: InMemoryJsonStore<GameHistoryEntry[]>;
	game: PlayGameUseCase;
}

export interface MakeAppValueOptions {
	/** Characters (existing in `symbols.ts`) to seed one script card each for. */
	symbols?: readonly string[];
	/** Sentence ids (existing in `sentences.json`) to seed one card each for. */
	sentences?: readonly string[];
	/**
	 * Thai words (existing in `vocabulary.json`) to seed one
	 * `toneIdentification` card each for — what makes a word eligible for
	 * tone practice.
	 */
	toneWords?: readonly string[];
	/**
	 * Thai words (existing in `vocabulary.json`) to seed one *graduated*
	 * vocab card each for — what counts toward grammar prerequisites and so
	 * toward composition mode's unlocked set. `UNLOCKS_FIRST_GRAMMAR_POINT`
	 * is the derived set that unlocks exactly the first grammar point.
	 */
	graduatedVocab?: readonly string[];
	/**
	 * Grammar ids (existing in `grammar.json`) to seed one grammar card
	 * each for — what marks those points *learned*, letting later points
	 * unlock once their own prerequisites are met.
	 */
	learnedGrammar?: readonly string[];
	/**
	 * Pre-built cards to seed as-is, for shapes the named options above don't
	 * cover (e.g. a `selfValidation` sentence card, built with
	 * `makeSelfValidationSentenceCard`).
	 */
	extraCards?: readonly ReviewableCard[];
}

/**
 * A complete in-memory `AppContextValue`: every use case and service the
 * real `AppContext.tsx` wires, built over `InMemoryStorage` instead of
 * `localStorage`, plus a real `PlayGameUseCase` over an in-memory history
 * store. `refresh` and `checkAchievements` are inert stubs — pass overrides
 * if a test needs either to be observable.
 */
export function makeAppValue(options: MakeAppValueOptions = {}): AppHarness {
	const storage = new InMemoryStorage();
	const cardRepo = new StorageCardRepository(storage);
	const stateRepo = new StorageLearnerStateRepository(storage);
	const apprenticeService = new ApprenticeService(
		cardRepo,
		MAX_APPRENTICE_ITEMS,
		stateRepo,
	);
	const leechService = new LeechService(cardRepo);
	const learningService = new LearningService(
		cardRepo,
		stateRepo,
		apprenticeService,
	);
	const reviewService = new ReviewService(cardRepo, stateRepo, {
		// Sentence sessions are chosen by coverage of the material rather than
		// by per-card overdueness — see `SentenceCoverageSelector`.
		sentence: new SentenceCoverageSelector(
			sentenceData as unknown as SentenceEntry[],
		),
	});
	const vocabularyService = new VocabularyService(
		cardRepo,
		stateRepo,
		vocabularyData as VocabEntry[],
		apprenticeService,
	);
	const grammarService = new GrammarService(
		cardRepo,
		grammarData as unknown as GrammarEntry[],
		apprenticeService,
		vocabularyData as VocabEntry[],
	);
	const sentenceService = new SentenceService(
		cardRepo,
		sentenceData as unknown as SentenceEntry[],
		vocabularyService,
		apprenticeService,
	);

	cardRepo.saveAll((options.symbols ?? []).map(makeScriptCard));
	cardRepo.saveAll((options.sentences ?? []).map(makeSentenceCard));
	cardRepo.saveAll((options.toneWords ?? []).map(makeToneVocabCard));
	cardRepo.saveAll((options.graduatedVocab ?? []).map(makeGraduatedVocabCard));
	cardRepo.saveAll((options.learnedGrammar ?? []).map(makeGrammarCard));
	cardRepo.saveAll([...(options.extraCards ?? [])]);

	const historyStore = new InMemoryJsonStore<GameHistoryEntry[]>();
	// Register every source the real `AppContext.tsx` registers — a harness
	// that registers a subset silently diverges from production per pool
	// (see task 1.3), which is how "works in the harness, empty in the app"
	// bugs are born.
	const game = new PlayGameUseCase(
		new GameItemSelectionService(
			[
				new SymbolGameItemSource(cardRepo),
				new WordGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
				new SentenceGameItemSource(
					cardRepo,
					sentenceData as unknown as SentenceEntry[],
				),
			],
			cardRepo,
			new ToneGameItemSource(cardRepo, vocabularyData as VocabEntry[]),
		),
		new StorageGameHistoryRepository(historyStore),
		// The real `GrammarService`, exactly as `AppContext.tsx` wires it — a
		// harness that stubs this diverges from production on the one
		// question composition mode asks (see task 1.3's own note above).
		() => grammarService.getUnlockedGrammarPoints(),
	);

	const value: AppContextValue = {
		state: storage.load(),
		refresh: () => {},
		lesson: new StartLessonUseCase(
			learningService,
			vocabularyService,
			grammarService,
			sentenceService,
		),
		review: new ConductReviewUseCase(
			reviewService,
			new NotificationScheduler(),
		),
		dashboard: new QueryDashboardUseCase(
			cardRepo,
			apprenticeService,
			leechService,
		),
		data: new ManageDataUseCase(stateRepo),
		items: new ManageItemsUseCase(cardRepo),
		vocab: vocabularyService,
		conversationPractice: new StubConversationPracticePort(),
		sentence: sentenceService,
		checkAchievements: () => [],
		game,
	};

	return { value, storage, cardRepo, historyStore, game };
}

export interface RenderWithAppOptions extends MakeAppValueOptions {
	/** Initial router entry, default `/`. */
	route?: string;
}

/**
 * Renders `ui` inside `<AppContext.Provider>` (a fresh in-memory
 * `AppContextValue`, with `overrides` merged in) and a `MemoryRouter`.
 * Returns Testing-Library's render result plus the harness internals.
 */
export function renderWithApp(
	ui: ReactElement,
	overrides: Partial<AppContextValue> = {},
	options: RenderWithAppOptions = {},
): RenderResult & { app: AppHarness } {
	const app = makeAppValue({
		symbols: options.symbols,
		sentences: options.sentences,
		toneWords: options.toneWords,
		graduatedVocab: options.graduatedVocab,
		learnedGrammar: options.learnedGrammar,
		extraCards: options.extraCards,
	});
	const value: AppContextValue = { ...app.value, ...overrides };
	const result = render(
		<AppContext.Provider value={value}>
			<MemoryRouter initialEntries={[options.route ?? "/"]}>{ui}</MemoryRouter>
		</AppContext.Provider>,
	);
	return Object.assign(result, { app: { ...app, value, game: value.game } });
}

